import math

def is_power_of_prime(x):
    if x < 2:
        return None
    # Find the smallest prime factor
    p = -1
    d = 2
    temp = x
    while d * d <= temp:
        if temp % d == 0:
            p = d
            while temp % d == 0:
                temp //= d
            break
        d += 1
    if temp > 1:
        if p == -1:
            p = temp
        elif temp != p:
            return None # Not a power of a single prime

    # Now check if x is a power of p
    if p == -1: return None

    # check if x = p^k
    val = p
    k = 1
    while val < x:
        val *= p
        k += 1

    if val == x and k > 1:
        return p
    return None

results = []
for m in range(1, 1000):
    for n in range(m, 1000):
        p1 = is_power_of_prime(m*m + n)
        if p1:
            p2 = is_power_of_prime(n*n + m)
            if p2 and p1 == p2:
                results.append((m, n, p1))

print(results)

def get_prime_power_divisors(n):
    divs = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            p = d
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            # all powers p^k for k from 2 to count
            for k in range(2, count + 1):
                divs.append((p, p**k))
        d += 1
    if temp > 1:
        # temp is a prime, but k=1, and we need k >= 2
        pass
    return divs

results = []
for m in range(1, 10000):
    # m^4 + m = m(m+1)(m^2-m+1)
    val = m * (m + 1) * (m**2 - m + 1)
    pp_divs = get_prime_power_divisors(val)
    for p, pa in pp_divs:
        if pa > m**2:
            n = pa - m**2
            if n > 0:
                # check if n^2 + m is a power of p
                # n^2 + m = p^b
                target = n**2 + m
                # check if target is a power of p
                temp_target = target
                if temp_target > 0:
                    while temp_target % p == 0:
                        temp_target //= p
                    if temp_target == 1:
                        # it is a power p^b. Check b > 1.
                        if target >= p**2:
                            results.append((m, n, p))

